                var optionDateTime = { "year": "numeric", "month": "2-digit", "day": "2-digit", "hour": "2-digit", "minute": "2-digit", "second": "2-digit" };

                /*var wscols = [{ wch: 6 },{ wch: 7 },{ wch: 10 },{ wch: 20 }];*/

