            //	c.push(controlName);
            //	c.push('\').hide();" class="btn btn-default">Close</button>');
            //}
            c.push('</div></div></div>');
            //c.push('<div class="modal-backdrop fade"></div>');
            ctrl.innerHTML = c.join('');
