var $$tabs = function (controlName) {
    var _msgError = {
        m1: 'Control not found',
        m2: 'Namespace not found',
        m3: 'Function not defined'
    };
    var ctrl = document.getElementById(controlName);
    if (ctrl == undefined) {
        console.log(_msgError.m1);
        return;
    }
    var sfx = 'jtse-tabs_' + controlName;
    var _ = {};
    if ($jt[sfx]) _ = $jt[sfx];
    var $create = function (o) {
        if (o) {
            _.namespace = o.namespace || '';
            _.fnEvSelected = o.fnEvSelected || [];
            _.titles = o.titles || [];
            _.fontSize = o.fontSize || [];
            _.fontWeight = o.fontWeight || [];
            _.textAlign = o.textAlign || [];
            //center|left|right
            ctrl.classList.add('jtse-tabs');
            var ul = document.createElement('UL');
            if (_.textAlign.length > 0) {
                ul.className = 'tabs text-' + _.textAlign;
            } else {
                ul.className = 'tabs';
            }
            var li, containers;
            for (var i = 0; i < _.titles.length; i++) {
                li = document.createElement('LI');
                if (i == 0) {
                    li.className = 'tab-link current';
                }
                else {
                    li.className = 'tab-link';
                }
                li.innerHTML = _.titles[i];
                li.setAttribute('data-tab', controlName + '-Tabs-' + i);
                li.setAttribute('data-index', i);
                if ((_.fontSize.length > 0) || (_.fontWeight.length > 0)) {
                    var c = [];
                    if (_.fontSize.length > 0) {
                        c.push('font-size:' + _.fontSize[i] + 'px; ');
                    }
                    if (_.fontWeight.length > 0) {
                        c.push('font-weight:' + _.fontWeight[i] + ';');
                    }
                    li.setAttribute('style', c.join(''));
                }
                li.addEventListener('click', function () {
                    selectTab(this);
                });
                if (_.fnEvSelected.length > 0) {
                    li.addEventListener('click', function () {
                        if (_.fnEvSelected[this.getAttribute('data-index')] != '') {
                            $jt[_.namespace][_.fnEvSelected[this.getAttribute('data-index')]](this);
                        }
                    });
                }
                ul.appendChild(li);
            }
            containers = ctrl.children;
            for (var i = 0; i < containers.length; i++) {
                if (i == 0) {
                    containers[i].className = 'tab-content current';
                }
                else {
                    containers[i].className = 'tab-content';
                }
                containers[i].id = controlName + '-Tabs-' + i;
            }
            ctrl.insertBefore(ul, ctrl.children[0]);
            ctrl.classList.add('show');
        }
    };
    var selectTab = function (obj) {
        var ul = obj.parentElement, li;
        for (var i = 0; i < ul.children.length; i++) {
            li = ul.children[i];
            li.classList.remove('current');
            document.getElementById(li.getAttribute('data-tab')).className = 'tab-content';
        }
        obj.className = 'tab-link current';
        document.getElementById(obj.getAttribute('data-tab')).className = 'tab-content current';
    };
    return {
        create: function (titles) {
            $create(titles);
        }
    };
};
var $$tooltip = function (controlName) {
    var ctrl = document.getElementById(controlName);
    var $create = function (o) {
        if (ctrl != undefined && o.Tooltip != undefined) {
            var tooltip = document.getElementById(o.Tooltip);
            var divHeader = tooltip.children[0];
            if (o.ClassHeader != undefined)
                divHeader.classList.add(o.ClassHeader);
            if (o.DataHeader != undefined)
                divHeader.innerHTML = o.DataHeader;
            var divBody = tooltip.children[1];
            if (o.ClassBody != undefined)
                divBody.classList.add(o.ClassBody);
            if (o.DataBody != undefined)
                divBody.innerHTML = o.DataBody;
            ctrl.setAttribute('data-tooltip', o.Tooltip);
            ctrl.classList.add('show');
            ctrl.onmouseover = function (event) { ubicarTooltip(true); };
            ctrl.onmouseout = function (event) { ubicarTooltip(false); };
        }
    };
    var ubicarTooltip = function (show) {
        var tooltip = document.getElementById(ctrl.getAttribute('data-tooltip'));
        if (show) {
            var c = document.getElementsByTagName('view-root')[0].children[0].getBoundingClientRect();
            var cHeight = c.height.toFixed(0) * 1;
            var cWidth = c.width.toFixed(0) * 1;
            var t = tooltip.getBoundingClientRect();
            var tHeight = t.height.toFixed(0) * 1;
            var tWidth = t.width.toFixed(0) * 1;
            var p = ctrl.getBoundingClientRect();
            var pTop = p.top.toFixed(0) * 1;
            var pLeft = p.left.toFixed(0) * 1;
            var dif = (cWidth - pLeft) < tWidth ? pLeft = pLeft - tWidth : '';
            var dif = (cHeight - pTop) < tHeight ? pTop = pTop - tHeight : '';
            tooltip.style.top = pTop + 'px';
            tooltip.style.left = pLeft + 'px';
            tooltip.style.display = 'block';
        }
        else { tooltip.style.display = 'none'; }
    };
    var $createGeneral = function () {
        if (ctrl == undefined) {
            var div = document.createElement('DIV');
            div.id = controlName;
            div.className = 'jtse-tooltip';
            div.innerHTML = '<div class="tooltip-header"></div><div class="tooltip-body"></div>';
            document.body.appendChild(div);
        }
    };
    return {
        create: function (o) {
            $create(o);
        },
        createGeneral: function () {
            $createGeneral();
        }
    };
};
